const COLOR_ICONS: string = "var(--text-color)";

export type TLinkIcon = "browser" | "github" | "wiki" | "linkedin";

export const getLinkIcon = (name: TLinkIcon): string => {
  switch (name) {
    case "browser":
      return browserIcon;
    case "github":
      return gitHubLogo;
    case "wiki":
      return wikiIcon;
    case "linkedin":
      return linkedInLogo;
    default:
      return "";
  }
};

